mapper.select:
SELECT
    JSONExtractBool(ifNull(r.metadata, '{}'), 'can_serve_tiles') AS can_serve_tiles,
    JSONExtractString(ifNull(r.metadata, '{}'), 'wsi_serving', 'sealed_source') AS sealed_source,
    JSONExtract(ifNull(r.metadata, '{}'), 'wsi_serving', 'thumbnail_width', 'Nullable(UInt32)') AS thumbnail_width,
    JSONExtract(ifNull(r.metadata, '{}'), 'wsi_serving', 'thumbnail_height', 'Nullable(UInt32)') AS thumbnail_height
FROM resource r
PREWHERE r.cancer_study_id = (
        SELECT cancer_study_id FROM cancer_study WHERE cancer_study_identifier = #{studyId}
    )
    AND r.resource_id IN ('WSI_SAMPLE', 'WSI_PATIENT')
    AND r.patient_id = #{patientId}
WHERE JSONExtractString(ifNull(r.metadata, '{}'), 'slide_key') = #{slideKey}
LIMIT 1
